import { useTranslation } from "react-i18next";
import { resources } from "./i18n";

const supported = Object.keys(resources);
const LABEL: Record<string, string> = { en: "Language", es: "Idioma", fr: "Langue" };

/** A language in its own name: es → "Español". */
function nameOf(lng: string) {
  try {
    const name = new Intl.DisplayNames([lng], { type: "language" }).of(lng);
    return name ? name[0].toLocaleUpperCase(lng) + name.slice(1) : lng;
  } catch {
    return lng;
  }
}

/**
 * Generated by Localize.dev. Render it wherever people pick a language, e.g. in your header:
 * <LanguageSwitcher className="…" />
 * The choice is saved in localStorage ("lang") and restored on the next visit.
 */
export function LanguageSwitcher({ className }: { className?: string }) {
  const { i18n } = useTranslation();
  const current = [i18n.language, i18n.language?.split("-")[0], i18n.resolvedLanguage].map((l) => supported.find((s) => s === l)).find(Boolean) ?? supported[0];

  const change = (lng: string) => {
    i18n.changeLanguage(lng);
    document.documentElement.lang = lng;
    try {
      localStorage.setItem("lang", lng);
    } catch {
      // Private mode: the choice lasts until the page is closed.
    }
  };

  return (
    <select
      data-localize-ignore
      aria-label={LABEL[current.split("-")[0]] ?? LABEL.en}
      value={current}
      onChange={(e) => change(e.target.value)}
      className={className}
    >
      {supported.map((lng) => (
        <option key={lng} value={lng} lang={lng}>
          {nameOf(lng)}
        </option>
      ))}
    </select>
  );
}
